<?php
declare(strict_types=1);
header('Content-Type: text/html; charset=utf-8');
$view = ($_GET['view'] ?? 'world') === 'ifis' ? 'ifis' : 'world';
$items = [];
$dbPath = dirname(__DIR__) . '/storage/news.sqlite';
if (is_file($dbPath) && extension_loaded('pdo_sqlite')) {
 try {
  $db = new PDO('sqlite:' . $dbPath);
  $query = $db->prepare('SELECT title,url,source,published_at,summary FROM articles WHERE section=:section ORDER BY published_at DESC LIMIT 120');
  $query->execute(['section'=>$view]);
  $items = $query->fetchAll(PDO::FETCH_ASSOC);
 } catch (Throwable $e) { error_log($e->getMessage()); }
}
function esc(?string $value): string { return htmlspecialchars($value ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function category(array $item): string {
 $s = mb_strtolower(($item['title'] ?? '').' '.($item['summary'] ?? ''),'UTF-8');
 $groups = [
 'Politik'=>['politik','regierung','parlament','wahl','diplomat','minister','konflikt','krieg'],
 'Gesellschaft'=>['gesellschaft','stadt','wohnen','migration','sozial','demokratie'],
 'Wirtschaft'=>['wirtschaft','markt','handel','unternehmen','inflation','energiepreis'],
 'Technologie'=>['technologie','ki ','künstliche intelligenz','digital','software','forschung'],
 'Umwelt'=>['klima','umwelt','natur','wald','biodivers','wasser','erneuerbar'],
 'Gesundheit'=>['gesundheit','medizin','pflege','krankenhaus','patient','bewegung'],
 'Bildung'=>['bildung','schule','lehrer','unterricht','universität','lernen'],
 'Wissenschaft'=>['wissenschaft','studie','forscher','experiment']
 ];
 foreach($groups as $name=>$words){foreach($words as $word){if(str_contains($s,$word))return $name;}}
 return 'Weitere';
}
foreach($items as &$item){$item['category']=category($item);} unset($item);
?><!doctype html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ffffff">
<title><?= $view==='ifis'?'IFIS-Radar':'Weltlage' ?> · IFIS News</title>
<style>
:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Arial,sans-serif;color-scheme:light;--bg:#fff;--text:#17212e;--muted:#697587;--line:#e7eaf0;--soft:#f5f7fa;--accent:#2468d5;--hover:#eef4ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-size:15px;line-height:1.48}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.topbar{height:65px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:32px;padding:0 30px;position:sticky;top:0;background:var(--bg);z-index:5}.brand{font-size:25px;letter-spacing:-1px;white-space:nowrap}.brand strong{font-weight:780}.topnav{display:flex;height:100%;gap:18px}.topnav a{padding:19px 12px 16px;border-bottom:3px solid transparent;white-space:nowrap}.topnav a.active{border-color:var(--accent);font-weight:650}.top-actions{margin-left:auto;display:flex;gap:15px;align-items:center}.search{border:1px solid var(--line);background:var(--soft);border-radius:24px;padding:9px 15px;min-width:270px;color:var(--text)}.search::placeholder{color:var(--muted)}.iconbtn{border:0;background:transparent;color:var(--muted);padding:7px 9px;border-radius:8px}.iconbtn:hover,.side button:hover,.chip:hover{background:var(--hover)}.layout{display:grid;grid-template-columns:210px minmax(0,1fr) 270px;gap:28px;max-width:1520px;margin:auto;padding:25px 24px 100px}.side{border-right:1px solid var(--line);padding-right:15px}.side h3{font-size:12px;margin:23px 10px 8px;color:var(--muted);font-weight:650;text-transform:uppercase;letter-spacing:.06em}.side button{display:block;width:100%;text-align:left;border:0;background:transparent;padding:10px 12px;border-radius:9px;color:var(--muted)}.side button.active{background:var(--hover);color:var(--accent);font-weight:650}.feedhead{display:flex;align-items:baseline;justify-content:space-between;border-bottom:1px solid var(--line);padding:6px 0 13px;gap:12px}.feedhead h1{font-size:23px;letter-spacing:-.5px;margin:0}.muted{color:var(--muted)}.feedhead small{color:var(--muted);white-space:nowrap}.chips{display:flex;gap:8px;overflow:auto;padding:14px 0 16px;scrollbar-width:none}.chips::-webkit-scrollbar{display:none}.chip{border:1px solid var(--line);border-radius:18px;background:var(--bg);padding:6px 12px;white-space:nowrap;font-size:13px;color:var(--muted)}.chip.active{background:var(--text);color:var(--bg);border-color:var(--text)}.story{display:grid;grid-template-columns:120px minmax(0,1fr) auto;gap:17px;padding:17px 0;border-bottom:1px solid var(--line);align-items:start}.story.feature{grid-template-columns:minmax(0,1fr) auto;padding-top:8px}.story h2{font-size:17px;line-height:1.3;letter-spacing:-.25px;margin:3px 0 5px}.story.feature h2{font-size:23px}.story h2 a:hover{text-decoration:underline}.summary{color:var(--muted);font-size:14px;margin:0 0 7px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.meta{font-size:12px;color:var(--muted)}.cat{font-size:11px;font-weight:700;color:var(--accent)}.thumb{background:var(--soft);width:120px;height:82px;border-radius:9px;display:flex;align-items:center;justify-content:center;color:#a3afbd;font-size:24px}.story.feature .thumb{display:none}.story-actions{display:flex;gap:0}.story-actions button{border:0;background:transparent;padding:5px;color:var(--muted);font-size:20px}.story-actions button:hover,.story-actions button.saved{color:var(--accent)}.panel{border:1px solid var(--line);border-radius:12px;padding:16px;margin-bottom:15px}.panel h2{font-size:15px;margin:0 0 12px}.panel p{color:var(--muted);font-size:13px}.panel a{color:var(--accent)}.panel button{border:1px solid var(--line);border-radius:18px;padding:6px 10px;background:var(--bg);margin:0 5px 8px 0;color:var(--muted)}.empty{text-align:center;padding:75px 15px;color:var(--muted)}.empty .symbol{font-size:36px;color:#a6b1bf}.empty h2{color:var(--text);font-size:20px}.empty p{max-width:420px;margin:auto}.bottomnav{display:none}.hide{display:none!important}.subtle{font-size:12px;color:var(--muted)}.sectiontitle{font-size:14px;font-weight:650;margin:10px 0 0}.sidefooter{font-size:12px;color:var(--muted);padding:15px 10px}
@media(max-width:1150px){.layout{grid-template-columns:180px minmax(0,1fr);gap:22px}.right{display:none}}
@media(max-width:720px){.topbar{height:60px;padding:0 15px;gap:8px}.brand{font-size:23px}.topnav{position:absolute;top:60px;left:0;right:0;height:47px;justify-content:center;border-bottom:1px solid var(--line);background:var(--bg)}.topnav a{padding:11px 25px 9px}.top-actions{gap:0}.search{position:absolute;left:12px;right:12px;top:112px;width:calc(100% - 24px);min-width:0;display:none;z-index:4;background:var(--bg)}.search.open{display:block}.search-toggle{display:block}.layout{display:block;padding:61px 15px 90px}.side{display:none}.feedhead h1{font-size:20px}.feedhead{padding-top:5px}.feedhead small{font-size:11px}.story{grid-template-columns:83px minmax(0,1fr) auto;gap:10px;padding:14px 0}.thumb{width:83px;height:75px}.story h2{font-size:15px}.story.feature{grid-template-columns:minmax(0,1fr) auto}.story.feature h2{font-size:20px}.summary{font-size:13px;-webkit-line-clamp:2}.story-actions{flex-direction:column}.story-actions button{font-size:18px;padding:2px}.bottomnav{position:fixed;bottom:0;left:0;right:0;display:flex;justify-content:space-around;background:var(--bg);border-top:1px solid var(--line);padding:7px 0 max(8px,env(safe-area-inset-bottom));z-index:6}.bottomnav button,.bottomnav a{border:0;background:none;text-align:center;font-size:11px;color:var(--muted);min-width:60px}.bottomnav .ico{display:block;font-size:21px}.bottomnav .active{color:var(--accent)}.empty{padding:65px 15px}}
@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#15191f;--text:#e9edf3;--muted:#a0acba;--line:#313945;--soft:#202731;--accent:#8ab4ff;--hover:#26354a}.chip.active{background:#e9edf3;color:#15191f;border-color:#e9edf3}}
</style></head><body>
<header class="topbar"><a class="brand" href="?view=world"><strong>IFIS</strong> News</a><nav class="topnav" aria-label="Bereiche"><a href="?view=world" class="<?= $view==='world'?'active':'' ?>">Weltlage</a><a href="?view=ifis" class="<?= $view==='ifis'?'active':'' ?>">IFIS-Radar</a></nav><div class="top-actions"><input class="search" id="search" type="search" placeholder="Nachrichten durchsuchen …" aria-label="Nachrichten durchsuchen"><button class="iconbtn search-toggle" id="searchToggle" title="Suche" aria-label="Suche">⌕</button><button class="iconbtn" id="savedTop" title="Gemerkt" aria-label="Gemerkt">♧ <span class="desktoplabel">Gemerkt</span></button></div></header>
<div class="layout">
<aside class="side" aria-label="Themen"><button data-cat="Alle" class="active">◉ &nbsp; Alle Meldungen</button><?php foreach(['Politik','Gesellschaft','Wirtschaft','Technologie','Umwelt','Gesundheit','Bildung','Wissenschaft','Weitere'] as $c): ?><button data-cat="<?=esc($c)?>"><?=esc($c)?></button><?php endforeach; ?><h3>Ansicht</h3><button id="savedSide">☆ &nbsp; Gemerkt</button><button id="hiddenSide">Ausgeblendete Meldungen</button><div class="sidefooter">Weniger Ablenkung. Mehr geografischer Überblick.<br><a href="https://ifis.net">Über IFIS ↗</a></div></aside>
<main id="main"><div class="feedhead"><h1 id="feedTitle"><?= $view==='ifis'?'IFIS-Radar':'Weltlage' ?></h1><small><?=count($items)?> Meldungen</small></div>
<div class="chips" id="chips" aria-label="Themenfilter"><button class="chip active" data-cat="Alle">Alle</button><?php foreach(['Politik','Gesellschaft','Wirtschaft','Technologie','Umwelt','Gesundheit','Bildung','Wissenschaft','Weitere'] as $c): ?><button class="chip" data-cat="<?=esc($c)?>"><?=esc($c)?></button><?php endforeach; ?></div>
<div id="stories"><?php foreach($items as $i=>$item): ?><article class="story <?= $i===0?'feature':'' ?>" data-url="<?=esc($item['url'])?>" data-cat="<?=esc($item['category'])?>" data-search="<?=esc(mb_strtolower(($item['title']??'').' '.($item['summary']??'').' '.($item['source']??''),'UTF-8'))?>"><div class="thumb" aria-hidden="true">▤</div><div><div class="cat"><?=esc($item['category'])?></div><h2><a href="<?=esc($item['url'])?>" target="_blank" rel="noopener noreferrer"><?=esc($item['title'])?></a></h2><?php if(!empty($item['summary'])): ?><p class="summary"><?=esc($item['summary'])?></p><?php endif; ?><div class="meta"><?=esc($item['source'])?> · <?=esc($item['published_at'])?> ↗</div></div><div class="story-actions"><button class="save" aria-label="Meldung merken" title="Merken">☆</button><button class="dismiss" aria-label="Meldung ausblenden" title="Ausblenden">×</button></div></article><?php endforeach; ?></div>
<div class="empty <?= $items?'hide':'' ?>" id="empty"><div class="symbol">▤</div><h2>Noch keine Nachrichten importiert.</h2><p>Sobald die ersten Quellen eingebunden sind, erscheinen hier die aktuellen Meldungen – übersichtlich und ohne Ablenkung.</p></div><div class="empty hide" id="noMatches"><h2>Keine passenden Meldungen</h2><p>Versuche einen anderen Suchbegriff oder Filter.</p></div></main>
<aside class="right"><div class="panel"><h2>Auf einen Blick</h2><p>Die wichtigsten Meldungen erscheinen hier, sobald Nachrichten importiert wurden.</p></div><div class="panel"><h2>Themen im Fokus</h2><div id="focusTopics"><?php foreach(['Umwelt','Gesundheit','Bildung','Technologie','Gesellschaft'] as $c): ?><button data-cat="<?=esc($c)?>"><?=esc($c)?></button><?php endforeach; ?></div></div><div class="panel"><h2>IFIS-Perspektive</h2><p>Weltlage und IFIS-Radar bleiben bewusst getrennt: erst informieren, dann Zusammenhänge entdecken.</p><a href="https://ifis.net">IFIS entdecken ↗</a></div></aside>
</div>
<nav class="bottomnav" aria-label="Mobile Navigation"><a href="?view=world" class="<?= $view==='world'?'active':'' ?>"><span class="ico">▤</span>News</a><a href="?view=ifis" class="<?= $view==='ifis'?'active':'' ?>"><span class="ico">◎</span>Radar</a><button id="savedBottom"><span class="ico">☆</span>Gemerkt</button><button id="moreBottom"><span class="ico">☷</span>Themen</button></nav>
<script>
(()=>{'use strict';
const prefix='ifis-news-v1-',load=(k)=>{try{return JSON.parse(localStorage.getItem(prefix+k)||'[]')}catch{return []}},store=(k,v)=>{try{localStorage.setItem(prefix+k,JSON.stringify(v))}catch{}};
let saved=load('saved'),hidden=load('hidden'),mode='all',cat='Alle';
const stories=[...document.querySelectorAll('.story')],search=document.getElementById('search'),empty=document.getElementById('empty'),noMatches=document.getElementById('noMatches'),title=document.getElementById('feedTitle');
const base=title.textContent;
function refresh(){let count=0;for(const el of stories){const url=el.dataset.url;const show=(mode==='saved'?saved.includes(url):mode==='hidden'?hidden.includes(url):!hidden.includes(url))&&(cat==='Alle'||el.dataset.cat===cat)&&el.dataset.search.includes(search.value.trim().toLocaleLowerCase());el.classList.toggle('hide',!show);el.querySelector('.save').textContent=saved.includes(url)?'★':'☆';el.querySelector('.save').classList.toggle('saved',saved.includes(url));el.querySelector('.dismiss').textContent=mode==='hidden'?'↶':'×';el.querySelector('.dismiss').title=mode==='hidden'?'Wieder anzeigen':'Ausblenden';if(show)count++}
empty.classList.toggle('hide',stories.length>0||mode!=='all'||cat!=='Alle'||!!search.value);
noMatches.classList.toggle('hide',count>0||(!stories.length&&mode==='all'&&cat==='Alle'&&!search.value));
title.textContent=mode==='saved'?'Gemerkt':mode==='hidden'?'Ausgeblendet':cat==='Alle'?base:cat;
document.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('active',mode==='all'&&b.dataset.cat===cat));
document.getElementById('savedBottom').classList.toggle('active',mode==='saved');
}
function setCat(v){cat=v;mode='all';refresh()}
document.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click',()=>setCat(b.dataset.cat)));
document.querySelectorAll('.save').forEach(b=>b.addEventListener('click',()=>{const u=b.closest('.story').dataset.url;saved=saved.includes(u)?saved.filter(x=>x!==u):[...saved,u];store('saved',saved);refresh()}));
document.querySelectorAll('.dismiss').forEach(b=>b.addEventListener('click',()=>{const u=b.closest('.story').dataset.url;hidden=hidden.includes(u)?hidden.filter(x=>x!==u):[...hidden,u];store('hidden',hidden);refresh()}));
function showSaved(){mode='saved';cat='Alle';refresh();window.scrollTo({top:0,behavior:'smooth'})}
document.getElementById('savedTop').onclick=showSaved;document.getElementById('savedSide').onclick=showSaved;document.getElementById('savedBottom').onclick=showSaved;
document.getElementById('hiddenSide').onclick=()=>{mode='hidden';cat='Alle';refresh()};
document.getElementById('searchToggle').onclick=()=>{search.classList.toggle('open');search.focus()};
document.getElementById('moreBottom').onclick=()=>{document.getElementById('chips').scrollIntoView({behavior:'smooth',block:'center'});};
search.addEventListener('input',refresh);refresh();
})();
</script></body></html>